parameters.jsCode:
return [{ json: {
  institute: 'Your Academy', tz: 'Asia/Kolkata', academic_head_whatsapp: 'REPLACE_WITH_ACADEMIC_HEAD_NUMBER',
  exam_max: { JEE: 300, NEET: 720 }, neg_per_wrong: 1,
  history_weeks: 5, min_q_topic: 4, weak_acc: 0.5, strong_acc: 0.8, drop_alert_pp: 10, neg_alert_share: 0.15,
  faculty_weak_share: 0.4, faculty_min_students: 5
} }];

const cfg = $('Set CoachingOS Config').first().json;
const now = $now.setZone(cfg.tz).endOf('day');
const wk0 = now.minus({ days: 7 }), h0 = now.minus({ weeks: cfg.history_weeks + 1 });
const week = now.toFormat("kkkk-'W'WW");
const num = v => Number(v) || 0;
const parse = s => { s = String(s || ''); const m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  const d = m ? DateTime.fromObject({ day: +m[1], month: +m[2], year: +m[3] }, { zone: cfg.tz }) : DateTime.fromISO(s.slice(0, 10), { zone: cfg.tz });
  return d.isValid ? d : null; };
const sent = new Set($('Read Report Log').all().map(i => i.json.report_key).filter(Boolean));
const rows = $('Read Test Scores').all().map(i => i.json).filter(r => r.student_id && r.subject)
  .map(r => ({ ...r, d: parse(r.test_date) })).filter(r => r.d && r.d >= h0 && r.d <= now);
const students = $('Read Students Sheet').all().map(i => i.json).filter(s => s.student_id);
const agg = list => { const m = list.reduce((a, r) => ({ marks: a.marks + num(r.marks_obtained), max: a.max + num(r.max_marks),
  c: a.c + num(r.correct), i: a.i + num(r.incorrect), u: a.u + num(r.unattempted) }), { marks: 0, max: 0, c: 0, i: 0, u: 0 });
  return { ...m, pct: m.max ? Math.round(m.marks / m.max * 1000) / 10 : null, acc: m.c + m.i ? Math.round(m.c / (m.c + m.i) * 100) : null,
    attempt: m.c + m.i + m.u ? Math.round((m.c + m.i) / (m.c + m.i + m.u) * 100) : null, neg_lost: m.i * cfg.neg_per_wrong }; };
const by = (list, f) => list.reduce((m, r) => ((m[f(r)] = m[f(r)] || []).push(r), m), {});

const out = [], perStudent = [];
for (const s of students) {
  const mine = rows.filter(r => String(r.student_id) === String(s.student_id));
  const wkRows = mine.filter(r => r.d >= wk0), hRows = mine.filter(r => r.d < wk0);
  const stream = /neet/i.test(s.stream || '') ? 'NEET' : 'JEE';
  const overall = agg(wkRows), prev = agg(hRows);
  const subjects = Object.entries(by(mine, r => r.subject)).map(([sub, list]) => {
    const w = agg(list.filter(r => r.d >= wk0)), p = agg(list.filter(r => r.d < wk0));
    const series = Object.entries(by(list, r => r.test_id)).map(([t, l]) => ({ date: l[0].d.toFormat('dd LLL'), ts: l[0].d.toMillis(), pct: agg(l).pct }))
      .sort((a, b) => a.ts - b.ts).slice(-6);
    return { subject: sub, pct: w.pct, prev_pct: p.pct, delta: w.pct !== null && p.pct !== null ? Math.round((w.pct - p.pct) * 10) / 10 : null,
      accuracy: w.acc, attempt: w.attempt, neg_lost: w.neg_lost, neg_share: w.max ? Math.round(w.neg_lost / w.max * 100) : 0, series };
  }).sort((a, b) => a.subject.localeCompare(b.subject));
  const topics = Object.entries(by(mine, r => `${r.subject}|${r.topic || 'General'}`)).map(([k, l]) => {
    const a = agg(l), w = agg(l.filter(r => r.d >= wk0)); const [subject, topic] = k.split('|');
    return { subject, topic, q: a.c + a.i + a.u, acc: a.acc, q_week: w.c + w.i + w.u, acc_week: w.acc };
  }).filter(t => t.q >= cfg.min_q_topic && t.acc !== null);
  // weak = poor over 6 weeks OR poor this week (recent slip)
  const weak = topics.filter(t => t.acc < cfg.weak_acc * 100 || (t.q_week >= cfg.min_q_topic && t.acc_week !== null && t.acc_week < cfg.weak_acc * 100))
    .map(t => ({ ...t, acc: t.acc_week ?? t.acc, recent: t.acc >= cfg.weak_acc * 100 })).sort((a, b) => a.acc - b.acc).slice(0, 5);
  const strong = topics.filter(t => t.acc >= cfg.strong_acc * 100).sort((a, b) => b.acc - a.acc).slice(0, 3);
  const tests = new Set(wkRows.map(r => r.test_id)).size;
  const flags = [];
  if (!tests) flags.push('missed this week\'s tests');
  subjects.filter(x => x.delta !== null && x.delta <= -cfg.drop_alert_pp).forEach(x => flags.push(`${x.subject} down ${-x.delta} points`));
  subjects.filter(x => x.neg_share >= cfg.neg_alert_share * 100).forEach(x => flags.push(`${x.subject}: ${x.neg_lost} marks lost to negative marking`));
  perStudent.push({ s, stream, overall, prev, subjects, weak, strong, tests, flags });
}
// batch rank (this week)
const byBatch = by(perStudent.filter(p => p.overall.pct !== null), p => p.s.batch || 'All');
for (const list of Object.values(byBatch)) {
  list.sort((a, b) => b.overall.pct - a.overall.pct);
  list.forEach((p, i) => { p.rank = i + 1; p.batch_size = list.length; p.percentile = Math.round((1 - i / list.length) * 100); });
}
for (const p of perStudent) {
  const s = p.s, key = `${s.student_id}|${week}`;
  if (sent.has(key) || /yes|true/i.test(String(s.opted_out || '')) || !s.parent_whatsapp) continue;
  out.push({ json: { type: 'student', report_key: key, week, student_id: s.student_id, name: s.name, first_name: String(s.name || '').split(' ')[0],
    batch: s.batch || '', stream: p.stream, parent_name: s.parent_name || 'Parent', parent_whatsapp: String(s.parent_whatsapp).replace(/\D/g, ''),
    language: s.language || 'English', mentor: s.mentor || '', mentor_whatsapp: String(s.mentor_whatsapp || '').replace(/\D/g, ''),
    tests_this_week: p.tests, overall_pct: p.overall.pct, prev_pct: p.prev.pct,
    overall_delta: p.overall.pct !== null && p.prev.pct !== null ? Math.round((p.overall.pct - p.prev.pct) * 10) / 10 : null,
    projected_score: p.overall.pct !== null ? Math.round(p.overall.pct / 100 * cfg.exam_max[p.stream]) : null, exam_max: cfg.exam_max[p.stream],
    rank: p.rank || null, batch_size: p.batch_size || null, percentile: p.percentile || null,
    subjects: p.subjects, weak_topics: p.weak, strong_topics: p.strong, flags: p.flags } });
}
// faculty: batch-wide weak topics
const wkAll = rows.filter(r => r.d >= wk0);
const sb = by(wkAll, r => `${(students.find(s => String(s.student_id) === String(r.student_id)) || {}).batch || 'All'}|${r.subject}`);
const faculty = $('Read Faculty').all().map(i => i.json).filter(f => f.subject);
const facOut = [];
for (const [k, list] of Object.entries(sb)) {
  const [batch, subject] = k.split('|');
  const topicStats = Object.entries(by(list, r => r.topic || 'General')).map(([topic, l]) => {
    const perStu = Object.values(by(l, r => r.student_id)).map(agg).filter(a => a.acc !== null);
    const weakStu = perStu.filter(a => a.acc < cfg.weak_acc * 100).length;
    return { topic, students: perStu.length, weak_students: weakStu, weak_share: perStu.length ? Math.round(weakStu / perStu.length * 100) : 0,
      avg_acc: perStu.length ? Math.round(perStu.reduce((t, a) => t + a.acc, 0) / perStu.length) : null };
  }).filter(t => t.students >= cfg.faculty_min_students && t.weak_share >= cfg.faculty_weak_share * 100).sort((a, b) => b.weak_share - a.weak_share).slice(0, 6);
  if (!topicStats.length) continue;
  const f = faculty.find(x => x.subject === subject && (x.batch === batch)) || faculty.find(x => x.subject === subject && (!x.batch || x.batch === '*')) || {};
  facOut.push({ json: { type: 'faculty', week, batch, subject, faculty_name: f.faculty_name || `${subject} faculty`,
    faculty_whatsapp: String(f.faculty_whatsapp || '').replace(/\D/g, ''), faculty_email: f.faculty_email || '', topics: topicStats } });
}
const withPct = perStudent.filter(p => p.overall.pct !== null);
const summary = { type: 'summary', week, students: students.length, reports: out.length,
  missed: perStudent.filter(p => !p.tests).length, flagged: perStudent.filter(p => p.flags.length).length,
  avg_pct: withPct.length ? Math.round(withPct.reduce((t, p) => t + p.overall.pct, 0) / withPct.length * 10) / 10 : null,
  top_movers: withPct.filter(p => p.prev.pct !== null).map(p => ({ name: p.s.name, d: Math.round((p.overall.pct - p.prev.pct) * 10) / 10 }))
    .sort((a, b) => b.d - a.d).slice(0, 3), faculty_alerts: facOut.length };
return [...out, ...facOut, { json: summary }];

