const s = $('Route by Report Type').item.json;
const ai = $json.message?.content || {};
const arrow = d => d === null || d === undefined ? '' : d > 0 ? ` ▲${d}` : d < 0 ? ` ▼${-d}` : ' ➖';
const card = [`📊 *${s.first_name} – Week ${s.week.split('W')[1]} scorecard*`,
  s.projected_score !== null ? `Projected: *${s.projected_score}/${s.exam_max}*${s.rank ? ` · Rank ${s.rank}/${s.batch_size} in ${s.batch}` : ''}` : 'No test taken this week',
  ...s.subjects.filter(x => x.pct !== null).map(x => `• ${x.subject}: ${x.pct}%${arrow(x.delta)} · accuracy ${x.accuracy ?? '–'}%${x.neg_lost ? ` · −${x.neg_lost} negative` : ''}`),
  s.weak_topics.length ? `🔁 Revise: ${s.weak_topics.map(t => `${t.topic} (${t.subject})`).join(', ')}` : null,
  s.strong_topics.length ? `⭐ Strong: ${s.strong_topics.map(t => t.topic).join(', ')}` : null].filter(Boolean).join('\n');
const palette = ['#e4572e', '#17344d', '#2e9e5b', '#f39c12', '#8e44ad'];
const dates = [...new Set(s.subjects.flatMap(x => x.series.map(p => p.date)))];
const chart = { type: 'line', data: { labels: dates, datasets: s.subjects.map((x, i) => ({ label: x.subject, fill: false, borderColor: palette[i % 5],
  data: dates.map(d => (x.series.find(p => p.date === d) || {}).pct ?? null), spanGaps: true })) },
  options: { title: { display: true, text: 'Subject % over recent tests' }, scales: { yAxes: [{ ticks: { min: 0, max: 100 } }] } } };
return { json: { ...s, ai_headline: ai.headline || '', concern: ai.concern_level || 'none',
  wa_text: `${ai.message || ''}\n\n${card}\n\n💬 Reply *CALL* to speak with the mentor, or ask any question here.`,
  chart_url: dates.length >= 2 ? 'https://quickchart.io/chart?w=700&h=380&bkg=white&c=' + encodeURIComponent(JSON.stringify(chart)) : '' } };

for (const { json: j } of $input.all()) {
  const v = j.value || j.entry?.[0]?.changes?.[0]?.value || j;
  const m = (v.messages || [])[0];
  if (!m) continue;
  const text = m.text?.body || m.button?.text || m.interactive?.button_reply?.title || '';
  if (!text) continue;
  return [{ json: { phone: String(m.from).replace(/\D/g, ''), text: text.slice(0, 800) } }];
}
return [];

const r = $('Parse Parent Reply').first().json;
const s = $('Find Student by Parent Number').first()?.json || {};
const rep = $input.all().map(i => i.json).filter(x => x.report_key).sort((a, b) => String(b.sent_at).localeCompare(String(a.sent_at)))[0] || {};
return [{ json: { phone: r.phone, text: r.text, known: !!s.student_id, student_id: s.student_id || '', student: s.name || '',
  parent_name: s.parent_name || 'Parent', language: s.language || 'English', batch: s.batch || '', mentor: s.mentor || '',
  mentor_whatsapp: String(s.mentor_whatsapp || '').replace(/\D/g, ''), latest_report: rep.summary_sent || '', weak_topics: rep.weak_topics || '',
  projected_score: rep.projected_score || '', week: rep.week || '' } }];

